<template><view class="page harvest-native">
 <view class="hero"><text class="title">采收协同</text><button size="mini" @click="exportSnapshot">导出当前方案</button><text class="muted">{{farmName}} · {{plan ? 'V'+plan.version+' · '+label(plan.status) : '尚未生成计划'}}</text></view>
 <view class="tabs"><view class="ui-measured-touch" v-for="item in tabs" :key="item.key" :class="{active:tab===item.key}" @click="tab=item.key">{{item.label}}</view></view>
 <view v-if="error" class="error">{{error}}<button size="mini" @click="load">重试</button></view><view v-if="loading" class="card muted">正在加载…</view>
 <template v-if="overview">
  <view v-if="tab==='plan'"><view class="card"><view class="buttons"><button size="mini" :disabled="busy" @click="generate">生成采收计划</button><button v-if="plan" size="mini" @click="operate('负责人确认',planUrl+'/approve',[note('reason','确认说明',true)])">负责人确认</button><button v-if="plan" size="mini" @click="operate('发布计划',planUrl+'/publish',[])">发布计划</button></view><business-detail :value="plan || {plots:overview.plots,resources:overview.resources}"/></view></view>
  <view v-if="tab==='dispatch'"><view class="card"><text class="muted">待执行 / 进行中 {{riskSummary.active}} 单 · 需关注 {{riskSummary.risks}} 单 · 剩余 {{riskSummary.area.toFixed(2)}} 亩 · 用工 {{riskSummary.people}} 人次</text><view class="buttons"><button size="mini" @click="riskOnly=!riskOnly">{{riskOnly?'显示全部':'只看天气风险'}}</button><button size="mini" @click="selectRisk">选择可重排风险单</button></view><text class="muted">选择待执行派单，结合天气和资源预览重排。</text><button size="mini" :disabled="!selectedIds.length" @click="riskPreview">批量预览重排（{{selectedIds.length}}）</button></view><view v-for="d in filteredDispatches" :key="d.id" class="card"><view class="dispatch-head"><checkbox :checked="selectedIds.includes(d.id)" :disabled="!['PLANNED'].includes(d.status)" color="#0f7a45" @click="toggle(d)"/><view><text class="strong">{{d.plotName}}</text><text class="muted block">{{d.dispatchDate}} · {{d.shiftStart}}—{{d.shiftEnd}}</text></view><text class="tag">{{label(d.status)}}</text></view><view class="metrics"><text>计划 {{d.area}} 亩</text><text>已采 {{d.actualArea || 0}} 亩</text><text>用工 {{d.assignedPeople}} / {{d.people}}</text></view><text v-if="needsAttention(d)" class="risk">{{riskFor(d).reasons.join('；')}}</text><view class="buttons"><button size="mini" @click="viewWeather(d)">班次天气</button><button size="mini" @click="operate('回写采收进度',dispatchUrl(d)+'/progress',[select('status','状态',choice({RUNNING:'开始执行',DONE:'已完成'}),true),number('actualArea','累计已采面积（亩）',true),note('note')],d)">回写进度</button><button size="mini" @click="expanded[d.id]=!expanded[d.id]">{{expanded[d.id]?'收起':'人员与农机'}}</button></view>
   <view v-if="expanded[d.id]"><view v-for="w in d.workers || []" :key="w.id" class="subcard"><text>{{w.workerName}} · {{label(w.attendanceStatus)}}</text><text class="muted block">计划 {{w.plannedHours}} 小时 · 实际 {{w.actualHours}} 小时</text><button size="mini" @click="operate('人员出勤回写',dispatchUrl(d)+'/workers/'+w.id+'/progress',[select('attendanceStatus','出勤状态',choice({PRESENT:'已到岗',ABSENT:'缺勤',DONE:'完成'}),true),number('actualHours','累计实际工时',true),number('actualArea','累计采收面积（亩）',true),note('note')],w)">登记出勤</button></view>
   <view v-for="m in d.machineDetails || []" :key="m.id" class="subcard"><text class="strong">{{m.machineName}} · {{label(m.status)}}</text><text class="muted block">机手 {{m.operatorWorkerName || '待调度'}} · 已作业 {{m.actualArea}} 亩</text><view class="buttons"><button size="mini" @click="operate('农机进度回写',machineUrl(d,m)+'/progress',[select('status','状态',choice({RUNNING:'作业中',DONE:'已完成'}),true),number('actualHours','累计实际工时',true),number('actualArea','累计作业面积（亩）',true),note('note')],m)">回写作业</button><button size="mini" @click="operate('登记故障',machineUrl(d,m)+'/faults',[note('description','故障描述',true),select('severity','严重程度',choice({GENERAL:'一般',CRITICAL:'严重'}),true),number('actualHours','累计实际工时',true),number('actualArea','累计作业面积（亩）',true)],m)">登记故障</button></view></view>
   <view v-for="fault in d.machineFaults || []" :key="fault.id" class="subcard"><text>{{fault.machineName}} · {{fault.description}}</text><text class="muted block">{{label(fault.status)}} · {{fault.reportedAt}}</text><view class="buttons"><button v-if="fault.status==='OPEN'" size="mini" @click="resolveFault(d,fault)">恢复 / 换机</button><button size="mini" @click="faultPreview(fault)">故障影响重排</button></view></view></view>
  </view></view>
  <view v-if="tab==='weather'"><view class="card"><view class="buttons"><button size="mini" @click="operate('刷新真实天气','/harvest-window/weather/refresh',[],{farmId})">刷新预报</button><button v-if="plan" size="mini" @click="operate('核验待执行派单',planUrl+'/weather/verify',[])">核验派单</button></view><text class="muted">{{overview.weatherInfo?.provider}} · {{overview.weatherInfo?.fetchedAt || '尚未取数'}}</text><text v-if="overview.weatherInfo?.error" class="risk">{{overview.weatherInfo.error}}</text><picker mode="date" :value="weatherDate" @change="weatherDate=$event.detail.value"><view class="date-picker">{{weatherDate || '选择日期'}} ⌄</view></picker><view v-if="weatherDispatch" class="notice">{{weatherDispatch.plotName}} · {{weatherDispatch.shiftStart}}—{{weatherDispatch.shiftEnd}}</view><hourly-weather-bars :hours="hours" :date="weatherDate" :dispatch="weatherDispatch"/><view v-for="hour in hours" :key="hour.time" :class="['hour',{unsafe:!hour.usable,shift:inShift(hour)}]"><view class="row"><text>{{hour.periodStart}}—{{String(hour.periodEnd || '').slice(11,16)}}</text><text>{{hour.temperature ?? '—'}}℃</text></view><text class="muted block">降水 {{hour.rainMm ?? '—'}}mm · 概率 {{hour.precipitationProbability ?? '—'}}% · 风速 {{hour.windSpeedMs ?? '—'}}m/s</text><text class="block">{{hour.note || (hour.usable?'满足天气条件':'不可作业')}}</text></view></view></view>
  <view v-if="tab==='history'" class="card"><business-detail :value="{events:plan?.events,reschedules:plan?.reschedules,riskReschedules:plan?.riskReschedules}"/></view>
 </template>
 <view v-if="editor" class="overlay"><view class="head"><text>{{editor.title}}</text><button size="mini" :disabled="busy" @click="closeEditor">关闭</button></view><scroll-view scroll-y class="body"><business-fields :fields="editor.fields" v-model="form" :farm-id="farmId" :disabled="busy" @ready="ready=$event"/><view v-if="editor.preview"><view v-for="d in benefitDispatches" :key="d.id" class="benefit-card"><view class="ui-measured-touch" @click="benefitExpanded[d.id]=!benefitExpanded[d.id]"><text class="strong">{{d.plotName}} · 收益测算依据</text><text class="muted block">{{benefitExpanded[d.id]?'收起':'选填：缺少参数时不计算收益'}}</text></view><business-fields v-if="benefitExpanded[d.id]" :fields="benefitFields" :model-value="benefitInputs[d.id] || {}" :disabled="busy" @update:model-value="benefitInputs[d.id]=$event"/></view></view><view v-if="preview" class="preview"><text class="strong">重排预览与前后对比</text><business-detail :value="preview"/><business-fields :fields="confirmFields" v-model="confirmation" :disabled="busy"/></view><view v-if="saveError" class="error">{{saveError}}</view><view style="height:50rpx"/></scroll-view><view class="bottom"><button class="primary" :loading="busy" :disabled="busy||!ready" @click="submit">{{editor.preview?'重新预览':editor.title}}</button><button v-if="preview" class="primary" :disabled="busy||preview.canApply===false||preview.blockedCount>0" @click="applyPreview">负责人确认应用</button></view></view>
 </view></template>
<script setup lang="ts">
import {saveText} from '@/utils/business-files'
async function exportSnapshot(){try{if(!plan.value)throw new Error('请先选择方案');await saveText('采收计划.json',JSON.stringify(plan.value,null,2))}catch(e:any){error.value=e.message}}
import {dispatchWeatherRisk,hourKey,shiftOverlap} from '@/utils/harvest-weather-risk'
import {ref,computed,watch} from 'vue'
import HourlyWeatherBars from '@/components/hourly-weather-bars/hourly-weather-bars.vue'
import {onShow,onHide,onBackPress,onPullDownRefresh} from '@dcloudio/uni-app'
import {call,text,number,date,note,select,yesno,choice,statusLabels,validateFields} from '@/api/native-business'
import type {Row,Field} from '@/api/native-business'
import {resolveCurrentFarm} from '@/utils/auth-helper'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {productionContextVersion} from '@/utils/request'
import BusinessFields from '@/components/business-fields/business-fields.vue'
import BusinessDetail from '@/components/business-detail/business-detail.vue'
const tabs=[{key:'plan',label:'计划'},{key:'dispatch',label:'派单'},{key:'weather',label:'天气'},{key:'history',label:'留痕'}]
const tab=ref('plan'),farmId=ref(''),farmName=ref(''),overview=ref<Row>(),loading=ref(false),error=ref(''),busy=ref(false),saveError=ref(''),ready=ref(false)
const plan=computed(()=>overview.value?.latestPlan),planUrl=computed(()=>'/harvest-window/plans/'+plan.value?.id)
const riskOnly=ref(false)
const riskFor=(d:Row)=>dispatchWeatherRisk(d,overview.value?.weatherInfo)
const needsAttention=(d:Row)=>{const r=riskFor(d);return r.active&&r.status!=='CLEAR'}
const riskSummary=computed(()=>{const active=(plan.value?.dispatches||[]).filter((d:Row)=>riskFor(d).active),risks=active.filter(needsAttention);return {active:active.length,risks:risks.length,area:risks.reduce((n:number,d:Row)=>n+Math.max(0,Number(d.area||0)-Number(d.actualArea||0)),0),people:risks.reduce((n:number,d:Row)=>n+Number(d.people||0),0)}})
const filteredDispatches=computed(()=>(plan.value?.dispatches||[]).filter((d:Row)=>!riskOnly.value||needsAttention(d)))
function selectRisk(){selectedIds.value=filteredDispatches.value.filter((d:Row)=>d.status==='PLANNED'&&needsAttention(d)).slice(0,50).map((d:Row)=>d.id)}
const selectedIds=ref<string[]>([]),expanded=ref<Row>({}),weatherDate=ref(''),weatherDispatch=ref<Row>()
const hours=computed(()=>(overview.value?.weatherInfo?.hours||[]).filter((h:Row)=>!weatherDate.value||hourKey(h.periodStart).startsWith(weatherDate.value)))
const form=ref<Row>({}),confirmation=ref<Row>({}),preview=ref<Row>(),previewInput=ref<Row>(),editor=ref<{title:string;url:string;fields:Field[];base:Row;preview?:'risk'|'fault';solve?:boolean}>()
const benefitInputs=ref<Row>({}),benefitExpanded=ref<Row>({})
const benefitDispatches=computed(()=>(plan.value?.dispatches||[]).filter((d:Row)=>editor.value?.preview==='fault'||selectedIds.value.includes(d.id)))
const benefitFields:Field[]=[number('yieldKgPerMu','参考亩产（kg/亩）'),number('baselinePrice','原日期价格（元/kg）'),number('candidatePrice','候选日期价格（元/kg）'),number('worstPrice','保守价格（元/kg）'),{...number('baselineLossPct','原日期损耗率（%）'),max:100},{...number('candidateLossPct','候选损耗率（%）'),max:100},{...number('worstLossPct','保守损耗率（%）'),max:100},number('baselineLaborCost','原人工成本（元）'),number('candidateLaborCost','候选人工成本（元）'),number('baselineMachineCost','原农机运输成本（元）'),number('candidateMachineCost','候选农机运输成本（元）'),number('baselineOtherCost','原其他成本（元）'),number('candidateOtherCost','候选其他成本（元）'),number('adjustmentCost','调度追加费用（元）'),note('sourceNote','测算依据')]
const confirmFields=[note('reason','负责人确认说明',true),yesno('confirmed','已复核前后安排与资源'),yesno('outsideWindowConfirmed','已确认窗口外延期风险')]
let version=0,scope=0
const label=(s:any)=>statusLabels[s]||s
const dispatchUrl=(d:Row)=>planUrl.value+'/dispatches/'+d.id
const machineUrl=(d:Row,m:Row)=>dispatchUrl(d)+'/machines/'+m.id
function toggle(d:Row){if(d.status!=='PLANNED')return;selectedIds.value=selectedIds.value.includes(d.id)?selectedIds.value.filter(i=>i!==d.id):selectedIds.value.length<50?[...selectedIds.value,d.id]:selectedIds.value;preview.value=undefined}
function viewWeather(d:Row){weatherDispatch.value=d;weatherDate.value=d.dispatchDate;tab.value='weather'}
function inShift(h:Row){return shiftOverlap(h,weatherDispatch.value)}
async function load(){const run=++version;loading.value=true;error.value='';try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||'';scope=productionContextVersion();const result=await call('/harvest-window/overview','GET',undefined,{farmId:farmId.value});if(run!==version)return;overview.value=result;selectedIds.value=[];if(!weatherDate.value)weatherDate.value=result.weather?.[0]?.date||''}catch(e:any){if(run===version)error.value=e.message}finally{if(run===version){loading.value=false;uni.stopPullDownRefresh()}}}
function operate(title:string,url:string,fields:Field[],base:Row={}){if(busy.value)return;editor.value={title,url,fields,base};form.value=Object.fromEntries(fields.map(f=>[f.key,base[f.key]??f.default??'']));preview.value=undefined;confirmation.value={};benefitInputs.value={};benefitExpanded.value={};saveError.value='';ready.value=false}
function generate(){operate('生成采收计划','/harvest-window/plans/solve',[date('windowStart','窗口开始',true),date('windowEnd','窗口结束',true),note('note')]);editor.value!.solve=true}
function riskPreview(){operate('批量预览重排',planUrl.value+'/risk-reschedule/preview',[date('readyDate','最早可安排日期',true),date('searchEnd','搜索截止日期',true)],{dispatchIds:[...selectedIds.value]});editor.value!.preview='risk'}
function faultPreview(fault:Row){operate('故障影响预览',planUrl.value+'/fault-reschedule/preview',[date('readyDate','最早恢复日期',true),select('fallbackMode','窗口外兜底',choice({EXTEND_WINDOW:'顺延接续',NEXT_CYCLE:'下一周期待复核'}),true),date('fallbackDate','兜底日期')],{faultId:fault.id});editor.value!.preview='fault'}
function resolveFault(d:Row,f:Row){operate('故障处置',dispatchUrl(d)+'/machines/'+f.machineId+'/faults/'+f.id+'/resolve',[select('action','处置方式',choice({RECOVER:'恢复原机',REPLACE:'换机接续'}),true),note('resolution','处置说明',true),text('replacementMachineNo','替代设备编号'),text('replacementMachineName','替代设备名称')])}
function closeEditor(){if(busy.value)return;editor.value=undefined;preview.value=undefined}
function payload():Row {const e=editor.value!;const data:Row={};for(const key of ['farmId','dispatchIds','faultId'])if(e.base[key]!==undefined)data[key]=e.base[key];for(const f of e.fields){const value=form.value[f.key];if(f.required&&(value===undefined||String(value).trim()===''))throw new Error('请填写'+f.label);if(value===undefined||value==='')continue;if(f.type==='number'){const n=Number(value);if(!Number.isFinite(n)||n<(f.min??0))throw new Error(f.label+'无效');data[f.key]=n}else data[f.key]=value}if(e.preview){data.benefitInputs=Object.fromEntries(Object.entries(benefitInputs.value).map(([id,value])=>[id,validateFields(benefitFields,value)]))}if(e.solve)Object.assign(data,{farmId:farmId.value,plots:overview.value?.plots,resources:overview.value?.resources,weather:overview.value?.weather});if(data.windowStart>data.windowEnd||data.readyDate>data.searchEnd)throw new Error('日期范围无效');return data}
async function submit(){if(busy.value||!editor.value)return;saveError.value='';try{if(scope!==productionContextVersion()||isProductionOps())throw new Error('业务范围已变更，请重新进入');const data=payload();busy.value=true;const result=await call(editor.value.url,'POST',data);if(editor.value.preview){previewInput.value=JSON.parse(JSON.stringify(data));preview.value=result;confirmation.value={}}else{closeAfter();await load()}}catch(e:any){saveError.value=e.message;preview.value=undefined}finally{busy.value=false}}
function closeAfter(){editor.value=undefined;preview.value=undefined;uni.showToast({title:'已保存',icon:'success'})}
async function applyPreview(){if(busy.value||!preview.value||!editor.value)return;saveError.value='';try{if(scope!==productionContextVersion())throw new Error('业务范围已变更');if(!confirmation.value.reason?.trim()||!confirmation.value.confirmed)throw new Error('请填写确认说明并勾选复核');const p=preview.value;const outside=p.outsideWindowUsed||p.rows?.some((r:Row)=>r.outsideWindow);if(outside&&!confirmation.value.outsideWindowConfirmed)throw new Error('请确认窗口外延期风险');const body={...previewInput.value,...confirmation.value,...(editor.value.preview==='risk'?{previewToken:p.previewToken}:{fingerprint:p.fingerprint})};busy.value=true;await call(editor.value.url.replace('/preview','/apply'),'POST',body);closeAfter();await load()}catch(e:any){saveError.value=e.message;preview.value=undefined;confirmation.value={}}finally{busy.value=false}}
watch([form,benefitInputs],()=>{preview.value=undefined;confirmation.value={}},{deep:true})
onShow(()=>void load());onPullDownRefresh(()=>void load());onHide(()=>{version++;editor.value=undefined;preview.value=undefined});onBackPress(()=>{if(busy.value)return true;if(editor.value){closeEditor();return true}return false})
</script>
<style scoped>
.harvest-native{padding:24rpx 24rpx 60rpx}.hero{padding:12rpx 8rpx 26rpx}.title{display:block;font-size:40rpx;font-weight:700;color:#17492c}.muted{font-size:24rpx;color:#666666;line-height:1.6}.block{display:block;margin-top:8rpx}.tabs{display:flex;background:white;border-radius:16rpx;overflow:hidden;position:sticky;top:0;z-index:2}.tabs>view{flex:1;text-align:center;padding:24rpx 0;font-size:28rpx;border-bottom:5rpx solid transparent}.tabs .active{color:#0f7a45;border-color:#0f7a45;font-weight:700}.card{margin:22rpx 0;padding:26rpx;background:#fff;border-radius:18rpx}.buttons{display:flex;gap:14rpx;flex-wrap:wrap;margin:18rpx 0}.buttons button{margin:0;min-height:76rpx;line-height:76rpx;font-size:24rpx}.dispatch-head{display:flex;gap:12rpx;align-items:center}.dispatch-head>view{flex:1;min-width:0}.strong{font-weight:600;font-size:29rpx}.tag{font-size:24rpx;color:#187d4a}.metrics{display:flex;flex-wrap:wrap;gap:16rpx;margin:24rpx 0;font-size:25rpx}.risk,.error{display:block;background:#fff0e8;color:#a34229;padding:20rpx;border-radius:12rpx;font-size:25rpx;line-height:1.6;margin:16rpx 0}.subcard{padding:22rpx;background:#f5f7f2;border-radius:14rpx;margin-top:18rpx;font-size:27rpx}.hour{padding:22rpx;border-bottom:1rpx solid #e1e9de;font-size:26rpx}.unsafe{background:#fff5e9}.shift{border-left:6rpx solid #2988ad}.row{display:flex;justify-content:space-between}.date-picker{background:#eef4ed;padding:24rpx;margin-top:22rpx;font-size:28rpx}.notice{padding:20rpx;color:#236887;font-size:24rpx}.overlay{position:fixed;inset:0;top:var(--window-top,0px);z-index:90;background:#fff;display:flex;flex-direction:column}.head{display:flex;justify-content:space-between;align-items:center;padding:24rpx;font-size:30rpx;font-weight:600;border-bottom:1rpx solid #eee}.head button{margin:0}.body{flex:1;height:0;box-sizing:border-box;padding:0 28rpx}.bottom{padding:20rpx 28rpx calc(20rpx + env(safe-area-inset-bottom));display:flex;gap:16rpx}.bottom button{flex:1;font-size:27rpx;min-height:88rpx;line-height:88rpx}.primary{background:#0f7a45;color:white}.benefit-card{padding:24rpx;background:#f4f7f0;border-radius:14rpx;margin-top:20rpx}.preview{margin-top:28rpx;border-top:1rpx solid #d9e4d6;padding-top:24rpx}

/* 2026-11-20：逐页实测控件的48px触控区。 */
.ui-measured-touch { min-width:48px; min-height:48px; box-sizing:border-box; }
text.ui-measured-touch { display:inline-flex; align-items:center; justify-content:center; }
</style>
